import{Z as s,e as o,f as t,a0 as i}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Dropdown","description":"","frontmatter":{},"headers":[],"relativePath":"fields/dropdown.md","filePath":"fields/dropdown.md","lastUpdated":1781138569000}'),a={name:"fields/dropdown.md"};function n(l,e,r,d,p,h){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="dropdown" tabindex="-1">Dropdown <a class="header-anchor" href="#dropdown" aria-label="Permalink to &quot;Dropdown&quot;">​</a></h1><p>Use Dropdown when someone should choose from a defined list and the options do not need to be visible all at once.</p><p>Use Dropdown for compact choice fields, especially when the list is long. If the choices are few and should stay visible, Radio or Checkboxes may be clearer.</p><h2 id="choose-an-enquiry-type" tabindex="-1">Choose an Enquiry Type <a class="header-anchor" href="#choose-an-enquiry-type" aria-label="Permalink to &quot;Choose an Enquiry Type&quot;">​</a></h2><p>Add a Dropdown field named <strong>Enquiry Type</strong> to a contact form. Add options labelled <strong>Sales</strong> and <strong>Support</strong>, with values <code>sales</code> and <code>support</code>. Labels are the text visitors see; values are what conditions and integrations can use. Save the form, select Support and submit. Check the saved answer before connecting that choice to a notification condition.</p><h2 id="key-settings" tabindex="-1">Key Settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to &quot;Key Settings&quot;">​</a></h2><ul><li><strong>Options</strong> - Define the available choices. Keep option values stable once submissions, exports or integrations depend on them.</li><li><strong>Multiple selections</strong> - Allow one selected value or a list of selected values.</li><li><strong>Default value</strong> - Preselect one or more options for new submissions.</li><li><strong>Placeholder</strong> - Show an initial prompt before a value is selected.</li><li><strong>Use searchable dropdown</strong> - Let users filter options by typing. Recommended for long lists. The front end keeps the native <code>&lt;select&gt;</code> for submission and enhances it with Formie’s <code>combobox</code> module.</li><li><strong>Required</strong> - Force a choice before the form can be submitted.</li></ul><h2 id="bulk-add-options" tabindex="-1">Bulk Add Options <a class="header-anchor" href="#bulk-add-options" aria-label="Permalink to &quot;Bulk Add Options&quot;">​</a></h2><p>Use Bulk add options when you need to add a long list, such as countries, states, currencies or another repeated option set. You can start from Formie’s predefined options, choose which source field should be used for the label and value, then append those options to the field or replace the existing options.</p><p>You can also paste your own options into the bulk editor. Use one option per line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Australia|AU</span></span>
<span class="line"><span>New Zealand|NZ</span></span>
<span class="line"><span>United States|US</span></span></code></pre></div><p>If you only provide one value on a line, Formie uses it for both the label and value.</p><h2 id="option-sources" tabindex="-1">Option Sources <a class="header-anchor" href="#option-sources" aria-label="Permalink to &quot;Option Sources&quot;">​</a></h2><p>Instead of copying a long predefined or integration list into the static options table, set <strong>Options</strong> to <strong>Predefined</strong> or <strong>Integration</strong>. Formie resolves the list at render time and stores the selected label with the submission value.</p><p>See <a href="/fields/option-sources">Option Sources</a> for predefined lists, Mailchimp groups, CRM picklists, template mode, converting to static options, and validation behaviour.</p><h2 id="option-availability" tabindex="-1">Option Availability <a class="header-anchor" href="#option-availability" aria-label="Permalink to &quot;Option Availability&quot;">​</a></h2><p>Use the row menu on an option to set its <strong>availability</strong>:</p><ul><li><strong>Visible</strong> — Shown and selectable (default).</li><li><strong>Hidden</strong> — Removed from the front-end form without deleting the option. Existing submissions keep their stored value and label in the control panel, exports and email notifications.</li><li><strong>Disabled</strong> — Shown on the front-end form with HTML <code>disabled</code> so it is visible but cannot be selected.</li></ul><p>Only one state applies at a time. Prefer hiding over deleting an option once submissions may reference its value.</p><h2 id="searchable-dropdown" tabindex="-1">Searchable Dropdown <a class="header-anchor" href="#searchable-dropdown" aria-label="Permalink to &quot;Searchable Dropdown&quot;">​</a></h2><p>Enable <strong>Use searchable dropdown</strong> when the option list is long enough that scrolling a native <code>&lt;select&gt;</code> is awkward. Formie renders a normal dropdown on the server, then enhances it on the front end so users can type to filter choices.</p><ul><li>Works with single and multiple selection.</li><li>Placeholder and empty-value options are shown as prompt text, not as selectable choices.</li><li>Selected multi-select values appear as removable pills; already-selected options are hidden from the filtered list.</li><li>The underlying <code>&lt;select&gt;</code> is still submitted, so validation, conditions, calculations and integrations behave like a regular dropdown.</li></ul><p>The setting is also available on <a href="/fields/entries">Entries</a>, <a href="/fields/categories">Categories</a>, <a href="/fields/users">Users</a>, <a href="/fields/products">Products</a>, and <a href="/fields/recipients">Recipients</a> when <strong>Display type</strong> is <strong>Dropdown</strong>.</p><p>For JavaScript hooks and module events, see <a href="https://docs.verbb.io/formie/browser/modules/field/combobox" target="_blank" rel="noreferrer">Combobox module</a> in the browser docs.</p><h2 id="overriding-options" tabindex="-1">Overriding Options <a class="header-anchor" href="#overriding-options" aria-label="Permalink to &quot;Overriding Options&quot;">​</a></h2><p>If the options need to come from template logic, set the field’s <strong>Options</strong> type to <strong>Template</strong> in the form builder, then override the field’s <code>options</code> before rendering the form. See <a href="/fields/option-sources#template">Option Sources</a> and <a href="/templates/overriding-settings">Overriding Settings</a>.</p><h2 id="submitted-value" tabindex="-1">Submitted Value <a class="header-anchor" href="#submitted-value" aria-label="Permalink to &quot;Submitted Value&quot;">​</a></h2><p>Dropdown stores the selected option value. When multiple selections are enabled, it stores a list of selected option values.</p><p>When querying or saving submissions through GraphQL, the field handle is used as the field name. Query the form’s <code>formFields</code> and include <code>inputTypeName</code> if you need to confirm the generated input type for a specific form.</p><h2 id="theme-config" tabindex="-1">Theme Config <a class="header-anchor" href="#theme-config" aria-label="Permalink to &quot;Theme Config&quot;">​</a></h2><p>The Dropdown field can be targeted with the <code>dropdown</code> theme config key.</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    themeConfig: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        dropdown: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            fieldInput: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    class: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-dropdown-input&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Use theme config for class and attribute changes. Use a template override only when the <code>&lt;select&gt;</code> markup or option rendering needs to change.</p><p>For full Tailwind, Bootstrap and other framework examples, see <a href="https://github.com/verbb/formie-theme-configs" target="_blank" rel="noreferrer">Formie theme configs</a>.</p><h2 id="related-fields" tabindex="-1">Related Fields <a class="header-anchor" href="#related-fields" aria-label="Permalink to &quot;Related Fields&quot;">​</a></h2><ul><li>Use <a href="/fields/radio">Radio</a> when a short list should stay visible.</li><li>Use <a href="/fields/checkboxes">Checkboxes</a> when several choices can be selected and visibility matters more than compactness.</li></ul>`,36)])])}const g=s(a,[["render",n]]);export{u as __pageData,g as default};
